<header class="page-header"><div><p class="eyebrow">Relationships</p><h1>Companies</h1><p>Organizations and independent people used across campaigns.</p></div><div class="form-actions"><a class="button" href="<?= $escape($newUrl) ?>">New company</a><a href="<?= $escape($newContactUrl) ?>">New independent contact</a></div></header>
<nav class="tab-list" aria-label="Company record state"><a href="<?= $escape($activeUrl) ?>"<?= !$archived?' aria-current="page"':'' ?>>Active</a><a href="<?= $escape($archivedUrl) ?>"<?= $archived?' aria-current="page"':'' ?>>Archived</a></nav>
<form class="filter-bar" method="get" action="<?= $escape($indexUrl) ?>"><?php if($archived): ?><input type="hidden" name="archived" value="1"><?php endif; ?><label>Search<input name="q" value="<?= $escape($filters['q']) ?>"></label><label>Sort<select name="sort"><?php foreach(['name'=>'Name','updated'=>'Recently updated','location'=>'Location','industry'=>'Industry'] as $key=>$label): ?><option value="<?= $escape($key) ?>"<?= $filters['sort']===$key?' selected':'' ?>><?= $escape($label) ?></option><?php endforeach; ?></select></label><label>Direction<select name="direction"><option value="asc"<?= $filters['direction']==='asc'?' selected':'' ?>>Ascending</option><option value="desc"<?= $filters['direction']==='desc'?' selected':'' ?>>Descending</option></select></label><button>Apply</button><a href="<?= $escape($archived?$archivedUrl:$activeUrl) ?>">Clear</a></form>
<p><?= $escape($count) ?> result<?= $count===1?'':'s' ?>.</p><?php if($companies===[]): ?><section class="empty-state"><h2><?= $count===0&&$filters['q']!==''?'No matching companies':'No '.($archived?'archived':'active').' companies' ?></h2><p><?= $archived?'Archived companies will appear here.':'Create a company, or add an independent contact without one.' ?></p></section><?php else: ?><div class="table-scroll" tabindex="0" role="region" aria-label="Companies"><table><thead><tr><th>Company</th><th>Location</th><th>Industry</th><th>Active contacts</th></tr></thead><tbody><?php foreach($companies as $company): ?><tr><th scope="row"><a href="<?= $escape($showUrl((int)$company['id'])) ?>"><?= $escape($company['name']) ?></a></th><td><?= $escape($company['location']??'—') ?></td><td><?= $escape($company['industry']??'—') ?></td><td><?= $escape($company['contact_count']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
<?php if($pages>1): ?><nav class="pagination" aria-label="Company pages"><?php for($number=1;$number<=$pages;$number++): ?><a href="<?= $escape($indexUrl.'?'.http_build_query($filters+['page'=>$number])) ?>"<?= $number===$page?' aria-current="page"':'' ?>><?= $escape($number) ?></a><?php endfor; ?></nav><?php endif; ?>
